 RepairFixture(){static_cast<NavalAssetState&>(naval)=take(commit_naval_formation(state,catalog,observed,request,"fleet:4","naval_action:5"));static_cast<NavalAssetCatalog&>(ships)=catalog;ships.combat_policy=NavalBattlePolicy{};ships.repair_policy=NavalRepairPolicy{};ships.repair_policy->rules={{"patch","river_boat",2,20,2,40,{{"mass",4}}}};naval.vessels[0].integrity=0;common.state().next_instance_id=10;access.travel_services=&services;}
